package com.example.timewarp.feature.reservation.confirmation

import android.content.Context
import android.net.Uri
import android.widget.Toast
import androidx.activity.compose.rememberLauncherForActivityResult
import androidx.activity.result.contract.ActivityResultContracts
import androidx.compose.material3.Button
import androidx.compose.material3.Text
import androidx.compose.runtime.Composable
import androidx.compose.runtime.rememberCoroutineScope
import androidx.compose.ui.Modifier
import androidx.compose.ui.platform.LocalContext
import com.example.timewarp.domain.model.Eric_Reservation
import java.io.IOException
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext

@Composable
fun ReservationCSVButton(
    reservation: Eric_Reservation,
    modifier: Modifier = Modifier
) {
    val context = LocalContext.current
    val scope = rememberCoroutineScope()

    // Opens the system "Save as" screen. When the user picks a place and a name,
    // we get back a Uri that points at the new, empty file and write the CSV into it.
    val saveCsvLauncher = rememberLauncherForActivityResult(
        contract = ActivityResultContracts.CreateDocument("text/csv")
    ) { uri: Uri? ->
        // uri is null when the user backs out of the picker.
        if (uri != null) {
            scope.launch {
                val saved = writeTextToUri(context, uri, reservationCSV(reservation))
                Toast.makeText(
                    context,
                    if (saved) "CSV saved" else "Couldn't save the CSV",
                    Toast.LENGTH_SHORT
                ).show()
            }
        }
    }

    Button(
        onClick = { saveCsvLauncher.launch("reservation") },
        modifier = modifier
    ) {
        Text(text = "Download CSV")
    }
}

// Writes the text into the file the user picked. Runs off the main thread because it is disk I/O.
private suspend fun writeTextToUri(context: Context, uri: Uri, text: String): Boolean =
    withContext(Dispatchers.IO) {
        try {
            val stream = context.contentResolver.openOutputStream(uri, "wt")
                ?: return@withContext false
            stream.use { it.write(text.toByteArray(Charsets.UTF_8)) }
            true
        } catch (e: IOException) {
            false
        }
    }